def transform(grid):
    background = max(set(x for row in grid for x in row),
                     key=lambda x: sum(row.count(x) for row in grid))
    counts = {}
    for row in grid:
        c = 0
        while c < len(row):
            if row[c] == background:
                c += 1
                continue
            color = row[c]
            counts[color] = counts.get(color, 0) + 1
            while c < len(row) and row[c] == color:
                c += 1

    cells = []
    for color in sorted(counts, reverse=True):
        cells.extend([color] * counts[color])

    width = 3
    height = (len(cells) + width - 1) // width
    cells.extend([0] * (height * width - len(cells)))
    return [cells[i:i + width] for i in range(0, len(cells), width)]
